import {isAdmin} from '@/lib/auth';import {supabaseServer} from '@/lib/supabase/server';export default async function Analytics(){if(!await isAdmin())return <p>403</p>;const db=await supabaseServer();const [{count:students},{count:challenges},{data:submissions},{data:solves}]=await Promise.all([db.from('profiles').select('*',{count:'exact',head:true}),db.from('challenges').select('*',{count:'exact',head:true}),db.from('challenge_submissions').select('is_correct,challenge_id'),db.from('challenge_completions').select('awarded_points')]);const attempts=submissions?.length||0,correct=submissions?.filter(x=>x.is_correct).length||0;return <><h1>Learning Analytics (dasar)</h1><div className="gridcards">{[['Siswa',students||0],['Tantangan',challenges||0],['Submission',attempts],['Submission benar',correct],['Total XP diberikan',(solves||[]).reduce((s,x)=>s+x.awarded_points,0)]].map(([k,v])=><div className="panel" key={k}><h2>{k}</h2><p className="text-3xl">{v}</p></div>)}</div><p className="muted mt-5">Analisis kompetensi, kelas, dan rekomendasi adaptif merupakan pengembangan lanjutan.</p></>}